BEGIN;
CREATE TABLE public.blog_posts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id integer UNIQUE,
 slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug)<=160),
 title text NOT NULL CHECK(length(title) BETWEEN 3 AND 180), excerpt text NOT NULL DEFAULT '' CHECK(length(excerpt)<=500),
 body jsonb NOT NULL DEFAULT '[]', author text NOT NULL DEFAULT '' CHECK(length(author)<=100), category text NOT NULL DEFAULT '' CHECK(length(category)<=60), tags text[] NOT NULL DEFAULT '{}',
 featured boolean NOT NULL DEFAULT false, featured_image text NOT NULL DEFAULT '', featured_alt text NOT NULL DEFAULT '',
 seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', canonical text NOT NULL DEFAULT '', og_image text NOT NULL DEFAULT '',
 status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','published','archived')), scheduled_for timestamptz, published_at timestamptz,
 related_services text[] NOT NULL DEFAULT '{}', reading_minutes integer NOT NULL DEFAULT 1 CHECK(reading_minutes>0), version integer NOT NULL DEFAULT 1 CHECK(version>0),
 created_by uuid REFERENCES public.admin_users(id) ON DELETE SET NULL, updated_by uuid REFERENCES public.admin_users(id) ON DELETE SET NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(status<>'scheduled' OR scheduled_for IS NOT NULL), CHECK(status<>'published' OR published_at IS NOT NULL)
);
CREATE INDEX blog_publication_idx ON public.blog_posts(status,published_at DESC,scheduled_for);
CREATE INDEX blog_category_idx ON public.blog_posts(category);
CREATE INDEX blog_tags_idx ON public.blog_posts USING gin(tags);
-- Historical slugs stay reserved after deletion. Every alias resolves directly to the current slug.
CREATE TABLE public.blog_slugs(slug text PRIMARY KEY,post_id uuid REFERENCES public.blog_posts(id) ON DELETE SET NULL);
CREATE INDEX blog_slug_post_idx ON public.blog_slugs(post_id);
CREATE TABLE public.blog_revisions(
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,article_id uuid NOT NULL,post_id uuid REFERENCES public.blog_posts(id) ON DELETE SET NULL,
 version integer NOT NULL,actor_id uuid REFERENCES public.admin_users(id) ON DELETE SET NULL,action text NOT NULL,
 request_id uuid UNIQUE NOT NULL,command jsonb NOT NULL,snapshot jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(article_id,version)
);
CREATE TABLE public.blog_media(id uuid PRIMARY KEY,storage_path text NOT NULL UNIQUE,mime text NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp','image/gif')),bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 8388608),uploaded_by uuid REFERENCES public.admin_users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.blog_slugs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.blog_revisions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.blog_media ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.blog_posts,public.blog_slugs,public.blog_revisions,public.blog_media FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.blog_posts,public.blog_slugs,public.blog_revisions,public.blog_media TO service_role;
REVOKE ALL ON SEQUENCE public.blog_revisions_id_seq FROM PUBLIC,anon,authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.blog_revisions_id_seq TO service_role;
INSERT INTO storage.buckets(id,name,public) VALUES('blog-media','blog-media',false) ON CONFLICT(id) DO UPDATE SET public=false;

CREATE FUNCTION public.blog_validate_blocks(p_body jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$
DECLARE block jsonb; total integer=0;
BEGIN
 IF p_body IS NULL OR jsonb_typeof(p_body)<>'array' OR jsonb_array_length(p_body)>120 THEN RETURN false; END IF;
 FOR block IN SELECT value FROM jsonb_array_elements(p_body) LOOP
  IF jsonb_typeof(block) IS DISTINCT FROM 'object' OR jsonb_typeof(block->'text') IS DISTINCT FROM 'string' OR block->>'type' NOT IN ('paragraph','heading2','heading3','bulletList','orderedList','quote','code') OR block->>'type' IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(block) k WHERE k NOT IN ('type','text')) OR length(block->>'text')>8000 THEN RETURN false; END IF;
  total=total+length(block->>'text');
 END LOOP;
 RETURN total<=120000;
END $$;
ALTER TABLE public.blog_posts ADD CONSTRAINT blog_body_shape CHECK(public.blog_validate_blocks(body));

CREATE FUNCTION public.blog_mutate(p_actor uuid,p_action text,p_id uuid,p_expected_version integer,p_request uuid,p_data jsonb DEFAULT '{}',p_confirm_slug_change boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor public.admin_users%ROWTYPE;c public.blog_posts%ROWTYPE;v public.blog_posts%ROWTYPE;prior public.blog_revisions%ROWTYPE;command jsonb;result jsonb;word_count integer;stamp timestamptz=clock_timestamp();old_slug text;
BEGIN
 SELECT * INTO actor FROM admin_users WHERE id=p_actor FOR SHARE;
 IF actor.id IS NULL OR actor.is_active IS DISTINCT FROM true OR actor.role<>'super_admin' THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF p_request IS NULL OR p_action NOT IN ('create','update','delete') OR p_action IS NULL THEN RAISE EXCEPTION 'Invalid command' USING ERRCODE='22023'; END IF;
 command=jsonb_build_object('action',p_action,'id',p_id,'version',p_expected_version,'data',p_data,'confirm_slug',p_confirm_slug_change);
 PERFORM pg_advisory_xact_lock(47001);
 SELECT * INTO prior FROM blog_revisions WHERE request_id=p_request;
 IF prior.id IS NOT NULL THEN
  IF prior.actor_id IS DISTINCT FROM p_actor OR prior.command IS DISTINCT FROM command THEN RAISE EXCEPTION 'Submission key conflict' USING ERRCODE='23505'; END IF;
  RETURN prior.result;
 END IF;
 IF p_action<>'create' THEN
  SELECT * INTO c FROM blog_posts WHERE id=p_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'Article not found' USING ERRCODE='P0002'; END IF;
  IF c.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Article changed; reload before saving' USING ERRCODE='40001'; END IF;
 END IF;
 IF p_action='delete' THEN
  IF c.legacy_id IS NOT NULL THEN RAISE EXCEPTION 'Legacy URLs are protected' USING ERRCODE='22023'; END IF;
  result=jsonb_build_object('id',c.id,'deleted',true);
  INSERT INTO blog_revisions(article_id,post_id,version,actor_id,action,request_id,command,snapshot,result) VALUES(c.id,c.id,c.version+1,p_actor,p_action,p_request,command,to_jsonb(c),result);
  DELETE FROM blog_posts WHERE id=c.id;
 ELSE
  IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN ('title','slug','excerpt','body','author','category','tags','featured','featured_image','featured_alt','seo_title','seo_description','canonical','og_image','status','scheduled_for','related_services')) THEN RAISE EXCEPTION 'Invalid fields' USING ERRCODE='22023'; END IF;
  SELECT * INTO v FROM jsonb_populate_record(NULL::public.blog_posts,p_data);
  IF v.title IS NULL OR length(btrim(v.title)) NOT BETWEEN 3 AND 180 OR v.slug IS NULL OR length(v.slug)>160 OR v.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' OR NOT blog_validate_blocks(v.body)
   OR v.excerpt IS NULL OR length(v.excerpt)>500 OR v.author IS NULL OR length(v.author)>100 OR v.category IS NULL OR length(v.category)>60
   OR v.status IS NULL OR v.status NOT IN ('draft','scheduled','published','archived') OR v.featured IS NULL OR v.tags IS NULL OR cardinality(v.tags)>20
   OR EXISTS(SELECT 1 FROM unnest(v.tags) t WHERE t IS NULL OR length(t) NOT BETWEEN 1 AND 40)
   OR (SELECT count(DISTINCT lower(t)) FROM unnest(v.tags)t)<>cardinality(v.tags)
   OR v.related_services IS NULL OR cardinality(v.related_services)>8 OR EXISTS(SELECT 1 FROM unnest(v.related_services) x WHERE x IS NULL OR x NOT IN ('/services/software','/services/web-development','/services/mobile-app-development','/services/hardware','/services/hardware-repair','/services/networking-solutions','/services/it-support','/amc-plans'))
   OR v.featured_image IS NULL OR length(v.featured_image)>2048 OR v.og_image IS NULL OR length(v.og_image)>2048 OR v.featured_alt IS NULL OR length(v.featured_alt)>180
   OR v.seo_title IS NULL OR length(v.seo_title)>180 OR v.seo_description IS NULL OR length(v.seo_description)>320 OR v.canonical IS NULL OR (v.canonical<>'' AND v.canonical<>'https://vedtechservices.in/blog/'||v.slug)
   OR (v.featured_image<>'' AND length(v.featured_alt)=0) THEN RAISE EXCEPTION 'Invalid article' USING ERRCODE='22023'; END IF;
  IF (v.slug ~ '^[0-9]+$' AND (c.legacy_id IS NULL OR v.slug<>c.slug)) OR v.slug IN ('preview','feed','api') THEN RAISE EXCEPTION 'Reserved slug' USING ERRCODE='22023'; END IF;
  IF c.legacy_id IS NOT NULL AND (v.slug<>c.slug OR v.status<>'published') THEN RAISE EXCEPTION 'Legacy URLs must remain published at their existing slug' USING ERRCODE='22023'; END IF;
  IF v.status='scheduled' AND (v.scheduled_for IS NULL OR v.scheduled_for<=stamp) THEN RAISE EXCEPTION 'Choose a future schedule' USING ERRCODE='22023'; END IF;
  SELECT count(*) INTO word_count FROM regexp_split_to_table((SELECT coalesce(string_agg(b->>'text',' '),'') FROM jsonb_array_elements(v.body)b),'\s+') word WHERE length(word)>0;
  IF v.status IN ('published','scheduled') THEN
   IF length(v.title)<8 OR length(v.excerpt)<30 OR length(v.author)<2 OR length(v.category)<2 OR word_count<40 THEN RAISE EXCEPTION 'Article is not publication ready' USING ERRCODE='22023'; END IF;
   IF EXISTS(SELECT 1 FROM blog_posts b WHERE b.id IS DISTINCT FROM c.id AND b.status IN ('published','scheduled') AND (lower(b.title)=lower(v.title) OR md5(b.body::text)=md5(v.body::text))) THEN RAISE EXCEPTION 'Duplicate published article' USING ERRCODE='23505'; END IF;
  END IF;
  IF c.id IS NOT NULL AND c.slug<>v.slug AND c.published_at IS NOT NULL AND NOT p_confirm_slug_change THEN RAISE EXCEPTION 'Confirm the permanent slug redirect' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM blog_slugs s WHERE s.slug=v.slug AND (c.id IS NULL OR s.post_id IS DISTINCT FROM c.id)) THEN RAISE EXCEPTION 'Slug is reserved' USING ERRCODE='23505'; END IF;
  old_slug=c.slug;
  IF c.id IS NULL THEN INSERT INTO blog_posts(slug,title) VALUES(v.slug,v.title) RETURNING * INTO c; END IF;
  UPDATE blog_posts SET slug=v.slug,title=btrim(v.title),excerpt=v.excerpt,body=v.body,author=v.author,category=v.category,tags=v.tags,featured=v.featured,featured_image=v.featured_image,featured_alt=v.featured_alt,
   seo_title=v.seo_title,seo_description=v.seo_description,canonical=v.canonical,og_image=v.og_image,status=v.status,scheduled_for=CASE WHEN v.status='scheduled' THEN v.scheduled_for ELSE NULL END,
   published_at=CASE WHEN v.status='published' THEN CASE WHEN c.published_at IS NULL OR c.published_at>stamp THEN stamp ELSE c.published_at END WHEN v.status='scheduled' THEN coalesce(c.published_at,v.scheduled_for) ELSE c.published_at END,
   related_services=v.related_services,reading_minutes=GREATEST(1,ceil(word_count/200.0)::int),version=CASE WHEN p_action='create' THEN 1 ELSE c.version+1 END,created_by=coalesce(c.created_by,p_actor),updated_by=p_actor,updated_at=stamp
   WHERE id=c.id RETURNING * INTO c;
  INSERT INTO blog_slugs(slug,post_id) VALUES(c.slug,c.id) ON CONFLICT(slug) DO UPDATE SET post_id=EXCLUDED.post_id;
  result=jsonb_build_object('post',to_jsonb(c),'deleted',false);
  INSERT INTO blog_revisions(article_id,post_id,version,actor_id,action,request_id,command,snapshot,result) VALUES(c.id,c.id,c.version,p_actor,p_action,p_request,command,to_jsonb(c),result);
 END IF;
 INSERT INTO activity_logs(user_id,user_name,user_role,action,target_id,target_type,details) VALUES(actor.id,actor.email,actor.role,'BLOG_'||upper(p_action),c.id::text,'BLOG_POST',jsonb_build_object('version',c.version,'status',c.status,'previous_slug',old_slug));
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.blog_validate_blocks(jsonb),public.blog_mutate(uuid,text,uuid,integer,uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.blog_validate_blocks(jsonb),public.blog_mutate(uuid,text,uuid,integer,uuid,jsonb,boolean) TO service_role;
CREATE VIEW public.blog_public_posts AS SELECT id,legacy_id,slug,title,excerpt,body,author,category,tags,featured,featured_image,featured_alt,seo_title,seo_description,canonical,og_image,published_at,updated_at,reading_minutes,related_services FROM public.blog_posts WHERE (status='published' AND published_at<=now()) OR (status='scheduled' AND scheduled_for<=now());
REVOKE ALL ON public.blog_public_posts FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.blog_public_posts TO service_role;
-- Existing approved local articles are seeded below by the checked-in conversion script.
INSERT INTO public.blog_posts(id,legacy_id,slug,title,excerpt,body,author,category,tags,featured,featured_image,featured_alt,seo_title,seo_description,canonical,og_image,status,scheduled_for,related_services,published_at,created_at,updated_at,reading_minutes) SELECT id,legacy_id,slug,title,excerpt,body,author,category,tags,featured,featured_image,featured_alt,seo_title,seo_description,canonical,og_image,status,scheduled_for,related_services,published_at,created_at,updated_at,reading_minutes FROM jsonb_populate_recordset(NULL::public.blog_posts,$blogseed$[{"id":"47000000-0000-4000-8000-000000000001","legacy_id":1,"slug":"1","title":"10 Essential IT Security Tips for Small Businesses in 2026","excerpt":"Protect your business from cyber threats with these proven security strategies. Learn how to safeguard your data and maintain customer trust.","body":[{"type":"paragraph","text":"Cybersecurity is no longer just a concern for large corporations. In 2026, small businesses are increasingly targeted by cybercriminals who exploit vulnerabilities in their digital infrastructure."},{"type":"paragraph","text":"At VedTech Services, we've identified 10 essential security tips that every small business owner should implement today:"},{"type":"orderedList","text":"**Multi-Factor Authentication (MFA):** Enable MFA on all business accounts, including email, banking, and cloud storage.\n**Regular Backups:** Implement an automated backup strategy to protect against data loss and ransomware.\n**Employee Training:** Educate your team about phishing scams and safe browsing habits.\n**Software Updates:** Keep all software, operating systems, and firmware up to date to patch known security flaws.\n**Secure Wi-Fi:** Use strong passwords and encryption for your office Wi-Fi network.\n**Firewall Protection:** Deploy a robust firewall to monitor and control incoming and outgoing network traffic.\n**Access Control:** Grant employees access only to the data and systems they need for their roles.\n**Secure Mobile Devices:** Implement mobile device management (MDM) for remote work.\n**Incident Response Plan:** Have a clear plan in place for responding to security incidents.\n**Regular Audits:** Conduct periodic security assessments to identify and mitigate risks."},{"type":"paragraph","text":"Protecting your business is an ongoing process. By following these tips, you can significantly reduce your risk of a cyberattack and focus on growing your business."}],"author":"VedTech Team","category":"Security","tags":["Security","Business","Tips"],"featured":true,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","featured_alt":"10 Essential IT Security Tips for Small Businesses in 2026","seo_title":"10 Essential IT Security Tips for Small Businesses in 2026 - VedTech Blog","seo_description":"Protect your business from cyber threats with these proven security strategies. Learn how to safeguard your data and maintain customer trust.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","status":"published","scheduled_for":null,"related_services":[],"published_at":"2026-01-24T18:30:00.000Z","created_at":"2026-01-24T18:30:00.000Z","updated_at":"2026-01-24T18:30:00.000Z","reading_minutes":5},{"id":"47000000-0000-4000-8000-000000000002","legacy_id":2,"slug":"2","title":"Why Your Business Needs a Professional Website in 2026","excerpt":"Discover how a well-designed website can transform your business. From SEO benefits to customer engagement, learn why online presence matters.","body":[{"type":"paragraph","text":"In 2026, your website is often the first point of contact between your business and potential customers. A professional, user-friendly website is no longer a luxury—it's a necessity."},{"type":"paragraph","text":"Here's why your business needs a professional website:"},{"type":"bulletList","text":"**First Impressions Matter:** A modern website builds trust and credibility with your audience.\n**24/7 Availability:** Your website works for you around the clock, providing information and taking orders even when your office is closed.\n**Global Reach:** Expand your customer base beyond your local area with a powerful online presence.\n**SEO Benefits:** Improve your visibility on search engines like Google and attract more organic traffic.\n**Customer Engagement:** Provide a platform for customers to learn about your products, read reviews, and contact you easily.\n**Showcase Your Portfolio:** Highlight your work and success stories to attract new clients."},{"type":"paragraph","text":"At VedTech Services, we specialize in building high-performance websites that deliver results. Whether you're a startup or an established enterprise, we can help you create a digital presence that stands out."}],"author":"VedTech Team","category":"Web Development","tags":["Website","Business Growth","SEO"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","featured_alt":"Why Your Business Needs a Professional Website in 2026","seo_title":"Why Your Business Needs a Professional Website in 2026 - VedTech Blog","seo_description":"Discover how a well-designed website can transform your business. From SEO benefits to customer engagement, learn why online presence matters.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","status":"published","scheduled_for":null,"related_services":["/services/web-development"],"published_at":"2026-01-19T18:30:00.000Z","created_at":"2026-01-19T18:30:00.000Z","updated_at":"2026-01-19T18:30:00.000Z","reading_minutes":7},{"id":"47000000-0000-4000-8000-000000000003","legacy_id":3,"slug":"3","title":"Complete Guide to IT AMC Plans: What You Need to Know","excerpt":"Understanding Annual Maintenance Contracts for IT services. Learn how AMC plans can save costs and ensure smooth business operations.","body":[{"type":"paragraph","text":"An Annual Maintenance Contract (AMC) is a service agreement between your business and an IT service provider. It ensures that your IT infrastructure is regularly maintained, updated, and supported."},{"type":"paragraph","text":"Benefits of an IT AMC plan include:"},{"type":"orderedList","text":"**Predictable Costs:** Fixed annual fees help you budget for IT support without unexpected repair bills.\n**Priority Support:** Get faster response times for technical issues and emergency repairs.\n**Preventive Maintenance:** Regular check-ups help identify and resolve potential problems before they lead to downtime.\n**Extended Hardware Life:** Proper maintenance helps your computers, printers, and network equipment last longer.\n**Peace of Mind:** Focus on your core business while we handle your IT needs."},{"type":"paragraph","text":"VedTech Services offers flexible AMC plans tailored to the needs of small businesses, schools, and offices. Our expert engineers are just a call away!"}],"author":"VedTech Team","category":"IT Support","tags":["AMC","IT Support","Business"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","featured_alt":"Complete Guide to IT AMC Plans: What You Need to Know","seo_title":"Complete Guide to IT AMC Plans: What You Need to Know - VedTech Blog","seo_description":"Understanding Annual Maintenance Contracts for IT services. Learn how AMC plans can save costs and ensure smooth business operations.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","status":"published","scheduled_for":null,"related_services":["/services/it-support"],"published_at":"2026-01-14T18:30:00.000Z","created_at":"2026-01-14T18:30:00.000Z","updated_at":"2026-01-14T18:30:00.000Z","reading_minutes":6},{"id":"47000000-0000-4000-8000-000000000004","legacy_id":4,"slug":"4","title":"Mobile App vs Website: What's Right for Your Business?","excerpt":"Choosing between a mobile app and website? We break down the pros, cons, and costs to help you make the right decision for your business.","body":[{"type":"paragraph","text":"Deciding whether to build a mobile app or a website can be challenging. Both have their advantages, and the right choice depends on your business goals and target audience."},{"type":"paragraph","text":"**When to Choose a Website:**\n- **Reach:** Websites are accessible to anyone with a browser and an internet connection.\n- **Cost:** Developing and maintaining a website is generally more affordable than a mobile app.\n- **SEO:** Websites are easier for search engines to crawl and index."},{"type":"paragraph","text":"**When to Choose a Mobile App:**\n- **User Experience:** Apps offer a smoother, faster, and more personalized experience.\n- **Offline Access:** Some apps can provide functionality without an internet connection.\n- **Push Notifications:** Engage your users directly with timely alerts and updates.\n- **Native Features:** Leverage device hardware like cameras, GPS, and sensors."},{"type":"paragraph","text":"Many businesses benefit from having both—a responsive website for reach and a mobile app for loyalty. Let VedTech Services help you develop a comprehensive digital strategy."}],"author":"VedTech Team","category":"Mobile Development","tags":["Mobile App","Website","Strategy"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","featured_alt":"Mobile App vs Website: What's Right for Your Business?","seo_title":"Mobile App vs Website: What's Right for Your Business? - VedTech Blog","seo_description":"Choosing between a mobile app and website? We break down the pros, cons, and costs to help you make the right decision for your business.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","status":"published","scheduled_for":null,"related_services":["/services/mobile-app-development"],"published_at":"2026-01-09T18:30:00.000Z","created_at":"2026-01-09T18:30:00.000Z","updated_at":"2026-01-09T18:30:00.000Z","reading_minutes":8},{"id":"47000000-0000-4000-8000-000000000005","legacy_id":5,"slug":"5","title":"How to Choose the Right IT Service Provider for Your Business","excerpt":"Key factors to consider when selecting an IT partner. From expertise to response time, learn what makes a great IT service provider.","body":[{"type":"paragraph","text":"Your IT service provider is a critical partner in your business success. Choosing the right one can lead to increased efficiency, better security, and growth."},{"type":"paragraph","text":"Key factors to consider:"},{"type":"bulletList","text":"**Expertise and Experience:** Look for a provider with a proven track record in your industry.\n**Response Time:** Ensure they offer guaranteed response times and emergency support.\n**Range of Services:** Choose a partner who can handle all your needs, from hardware repair to software development.\n**Scalability:** Your IT provider should be able to grow with your business.\n**Customer Reviews:** Check testimonials and success stories from other clients.\n**Transparent Pricing:** Look for clear, upfront pricing without hidden fees."},{"type":"paragraph","text":"At VedTech Services, we pride ourselves on being a reliable, professional, and customer-focused IT partner. We treat your business as our own."}],"author":"VedTech Team","category":"Business Tips","tags":["IT Services","Business","Guide"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","featured_alt":"How to Choose the Right IT Service Provider for Your Business","seo_title":"How to Choose the Right IT Service Provider for Your Business - VedTech Blog","seo_description":"Key factors to consider when selecting an IT partner. From expertise to response time, learn what makes a great IT service provider.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","status":"published","scheduled_for":null,"related_services":[],"published_at":"2026-01-04T18:30:00.000Z","created_at":"2026-01-04T18:30:00.000Z","updated_at":"2026-01-04T18:30:00.000Z","reading_minutes":5},{"id":"47000000-0000-4000-8000-000000000006","legacy_id":6,"slug":"6","title":"Top 5 Technology Trends for Indian SMEs in 2026","excerpt":"Stay ahead of the curve with these emerging tech trends. From AI to cloud computing, discover what's shaping the future of business.","body":[{"type":"paragraph","text":"As we move further into 2026, several technology trends are set to reshape the landscape for small and medium enterprises (SMEs) in India."},{"type":"orderedList","text":"**AI and Automation:** SMEs are using AI to automate routine tasks, improve customer service, and gain insights from data.\n**Cloud-First Strategy:** More businesses are moving their operations to the cloud for better scalability, security, and remote work support.\n**Cybersecurity Resilience:** With the rise in cyber threats, SMEs are investing more in robust security solutions and employee training.\n**E-commerce Growth:** The push for digital sales continues, with more businesses launching their own online stores and apps.\n**Remote Collaboration Tools:** Tools for virtual meetings, project management, and team communication remain essential for modern businesses."},{"type":"paragraph","text":"Staying ahead of these trends can give your SME a competitive edge. VedTech Services is here to help you navigate the future of technology."}],"author":"VedTech Team","category":"Technology Trends","tags":["Trends","Technology","SME"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","featured_alt":"Top 5 Technology Trends for Indian SMEs in 2026","seo_title":"Top 5 Technology Trends for Indian SMEs in 2026 - VedTech Blog","seo_description":"Stay ahead of the curve with these emerging tech trends. From AI to cloud computing, discover what's shaping the future of business.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","status":"published","scheduled_for":null,"related_services":[],"published_at":"2025-12-29T18:30:00.000Z","created_at":"2025-12-29T18:30:00.000Z","updated_at":"2025-12-29T18:30:00.000Z","reading_minutes":6},{"id":"47000000-0000-4000-8000-000000000007","legacy_id":7,"slug":"7","title":"How to Troubleshoot Slow Internet on Windows 11","excerpt":"Is your internet crawling? Follow our step-by-step guide to identify and fix common connectivity issues on Windows 11.","body":[{"type":"paragraph","text":"# Knowledge Base: Troubleshooting Slow Internet"},{"type":"paragraph","text":"Slow internet can be frustrating, especially when you're working on tight deadlines. Here's a step-by-step troubleshooting guide for Windows 11 users:"},{"type":"heading2","text":"Step 1: Run the Network Troubleshooter\nWindows 11 has built-in tools that can automatically detect and fix common issues.\n1. Go to **Settings** > **System** > **Troubleshoot**.\n2. Select **Other troubleshooters**.\n3. Click **Run** next to **Internet Connections**."},{"type":"heading2","text":"Step 2: Update Network Drivers\nOutdated drivers are a common cause of poor connectivity.\n1. Right-click the **Start** button and select **Device Manager**.\n2. Expand **Network adapters**.\n3. Right-click your Wi-Fi or Ethernet adapter and select **Update driver**."},{"type":"heading2","text":"Step 3: Flush DNS Cache\nCorrupted DNS data can slow down page loading.\n1. Open **Command Prompt** as Administrator.\n2. Type `ipconfig /flushdns` and press Enter."},{"type":"heading2","text":"Step 4: Check for Background Apps\nApps running in the background can consume bandwidth.\n1. Press **Ctrl + Shift + Esc** to open **Task Manager**.\n2. Go to the **Performance** tab and click **Resource Monitor**.\n3. Look at the **Network** tab to see which apps are using the most data."},{"type":"paragraph","text":"Need more help? Contact VedTech Services for on-site or remote network support."}],"author":"Engineering Team","category":"Knowledge Base","tags":["Troubleshooting","Internet","Windows 11"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","featured_alt":"How to Troubleshoot Slow Internet on Windows 11","seo_title":"How to Troubleshoot Slow Internet on Windows 11 - VedTech Blog","seo_description":"Is your internet crawling? Follow our step-by-step guide to identify and fix common connectivity issues on Windows 11.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_d19bfcb7-b08f-4153-8d6b-3a56b1c14bac.jpg","status":"published","scheduled_for":null,"related_services":[],"published_at":"2026-01-31T18:30:00.000Z","created_at":"2026-01-31T18:30:00.000Z","updated_at":"2026-01-31T18:30:00.000Z","reading_minutes":10},{"id":"47000000-0000-4000-8000-000000000008","legacy_id":8,"slug":"8","title":"How-to: Set Up a Dual Monitor Workplace","excerpt":"Boost your productivity by adding a second monitor. We show you exactly how to connect and configure your dual-screen setup.","body":[{"type":"paragraph","text":"# How-to Guide: Dual Monitor Setup"},{"type":"paragraph","text":"Adding a second monitor is one of the easiest ways to increase your productivity. Here is how to get it done:"},{"type":"heading2","text":"1. Check Your Connections\nEnsure your computer has the necessary ports (HDMI, DisplayPort, or USB-C). Most modern laptops and desktops support at least two displays."},{"type":"heading2","text":"2. Connect the Monitor\nPlug in the video cable from your second monitor to your computer's video output. If you're using a laptop with only one HDMI port and you want two external monitors, you might need a **Docking Station**."},{"type":"heading2","text":"3. Configure Display Settings (Windows 11)\nOnce connected, Windows should detect the monitor automatically.\n1. Right-click on the Desktop and select **Display settings**.\n2. You'll see two boxes numbered 1 and 2. Click **Identify** to see which is which.\n3. Drag the boxes to match the physical position of your monitors.\n4. Scroll down to **Multiple displays** and ensure **Extend these displays** is selected."},{"type":"heading2","text":"4. Adjust Scaling and Resolution\nIf the text looks blurry or too small on one screen, adjust the **Scale** and **Display resolution** for each monitor individually."},{"type":"paragraph","text":"If you're having trouble with cables or adapters, VedTech Services can provide the hardware and setup assistance you need!"}],"author":"Hardware Dept","category":"How-to Guides","tags":["Productivity","Hardware","Setup"],"featured":false,"featured_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","featured_alt":"How-to: Set Up a Dual Monitor Workplace","seo_title":"How-to: Set Up a Dual Monitor Workplace - VedTech Blog","seo_description":"Boost your productivity by adding a second monitor. We show you exactly how to connect and configure your dual-screen setup.","canonical":"","og_image":"https://miaoda-site-img.s3cdn.medo.dev/images/KLing_81c94b3f-98d2-474e-93f2-ac5ecb11b096.jpg","status":"published","scheduled_for":null,"related_services":[],"published_at":"2026-02-04T18:30:00.000Z","created_at":"2026-02-04T18:30:00.000Z","updated_at":"2026-02-04T18:30:00.000Z","reading_minutes":8}]$blogseed$::jsonb);
INSERT INTO public.blog_slugs(slug,post_id) SELECT slug,id FROM public.blog_posts;

CREATE FUNCTION public.blog_public_search(p_q text DEFAULT '',p_category text DEFAULT '',p_tag text DEFAULT '',p_page integer DEFAULT 1)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb; pattern text;
BEGIN
 IF length(coalesce(p_q,''))>80 OR length(coalesce(p_category,''))>60 OR length(coalesce(p_tag,''))>40 OR p_page NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Invalid search' USING ERRCODE='22023'; END IF;
 pattern='%'||replace(replace(replace(coalesce(p_q,''),'\','\\'),'%','\%'),'_','\_')||'%';
 WITH matches AS (SELECT * FROM blog_public_posts p WHERE (coalesce(p_q,'')='' OR p.title ILIKE pattern OR p.excerpt ILIKE pattern) AND (coalesce(p_category,'')='' OR p.category=p_category) AND (coalesce(p_tag,'')='' OR p_tag=ANY(p.tags))),
 page AS (SELECT * FROM matches ORDER BY published_at DESC,id LIMIT 6 OFFSET (p_page-1)*6)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(p)-'body') FROM page p),'[]'::jsonb),'total',(SELECT count(*) FROM matches),
 'categories',coalesce((SELECT jsonb_agg(c.category ORDER BY c.category) FROM (SELECT DISTINCT category FROM blog_public_posts WHERE category<>'')c),'[]'::jsonb),
 'tags',coalesce((SELECT jsonb_agg(t.tag ORDER BY t.tag) FROM (SELECT DISTINCT unnest(tags) tag FROM blog_public_posts)t),'[]'::jsonb),
 'featured',coalesce((SELECT jsonb_agg(to_jsonb(f)-'body') FROM (SELECT * FROM blog_public_posts WHERE featured ORDER BY published_at DESC,id LIMIT 3)f),'[]'::jsonb)) INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.blog_public_search(text,text,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.blog_public_search(text,text,text,integer) TO service_role;
COMMIT;
